import{_ as a,o as i,c as r,ag as o}from"./chunks/framework.D9ghT4bC.js";const f=JSON.parse('{"title":"CoeHarMod Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"Community/Mods/CoeHarMod/changelog/index.md","filePath":"Community/Mods/CoeHarMod/changelog/index.md"}'),l={name:"Community/Mods/CoeHarMod/changelog/index.md"};function n(t,e,s,d,h,u){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="coeharmod-changelog" tabindex="-1">CoeHarMod Changelog <a class="header-anchor" href="#coeharmod-changelog" aria-label="Permalink to &quot;CoeHarMod Changelog&quot;">​</a></h1><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><ul><li>Top-bar counters can now be configured individually.</li><li>Updated the recommended game version to 4.21.10.2.</li></ul><h2 id="v3-3-12-for-4-21-8-2" tabindex="-1">v3.3.12 - for 4.21.8.2 <a class="header-anchor" href="#v3-3-12-for-4-21-8-2" aria-label="Permalink to &quot;v3.3.12 - for 4.21.8.2&quot;">​</a></h2><ul><li>Enabled immediate production overflow: applies on the same turn, finished units can move instantly</li></ul><h2 id="v3-3-11-for-4-21-8-2" tabindex="-1">v3.3.11 - for 4.21.8.2 <a class="header-anchor" href="#v3-3-11-for-4-21-8-2" aria-label="Permalink to &quot;v3.3.11 - for 4.21.8.2&quot;">​</a></h2><ul><li>Unit upkeep is fixed and no longer rises as the game progresses.</li><li>New mod versions are no longer distributed through GitHub Releases.</li></ul><h2 id="v3-3-10-for-4-19-15" tabindex="-1">v3.3.10 - for 4.19.15 <a class="header-anchor" href="#v3-3-10-for-4-19-15" aria-label="Permalink to &quot;v3.3.10 - for 4.19.15&quot;">​</a></h2><ul><li>Monks can now appear in the Civilopedia</li><li>Fixed the monk cap behaving abnormally</li><li>Fixed the Oracle&#39;s faith-buy discount actually increasing costs</li><li>Nerfed Byzantine heavy cavalry happiness: linear growth changed to square-root growth</li></ul><h2 id="v3-3-9-for-4-19-12" tabindex="-1">v3.3.9 - for 4.19.12 <a class="header-anchor" href="#v3-3-9-for-4-19-12" aria-label="Permalink to &quot;v3.3.9 - for 4.19.12&quot;">​</a></h2><h3 id="🏛️-building-adjustments" tabindex="-1">🏛️ Building adjustments <a class="header-anchor" href="#🏛️-building-adjustments" aria-label="Permalink to &quot;🏛️ Building adjustments&quot;">​</a></h3><ul><li><strong>Normal building price scaling removed</strong>: deleted the price-increase effect of all normal buildings</li><li><strong>District landmark scaling doubled</strong>: district landmark buildings&#39; price increase doubled</li></ul><h3 id="📜-opening-experience" tabindex="-1">📜 Opening experience <a class="header-anchor" href="#📜-opening-experience" aria-label="Permalink to &quot;📜 Opening experience&quot;">​</a></h3><ul><li><strong>Policy card unlock</strong>: new games auto-open all policy cards, simplifying the flow</li><li><strong>Era restriction</strong>: games can only start in the Ancient era, avoiding bugs from later-era starts</li><li><strong>Governor point reminder</strong>: event reminder when surplus governor points are unused</li></ul><h3 id="⚖️-happiness-system" tabindex="-1">⚖️ Happiness system <a class="header-anchor" href="#⚖️-happiness-system" aria-label="Permalink to &quot;⚖️ Happiness system&quot;">​</a></h3><ul><li>Adjusted the happiness bonus: every point of per-city average happiness gives all cities +2% of all yields (science, culture, faith, production, gold; not food)</li><li>Population growth limit: no growth when average happiness is below -4 (≤ -5)</li><li>Rebel trigger: may spawn rebels when average happiness is below -9 (≤ -10)</li><li>Fixed negative values in the happiness system not working</li></ul><h2 id="v3-3-8-for-4-19-11" tabindex="-1">v3.3.8 - for 4.19.11 <a class="header-anchor" href="#v3-3-8-for-4-19-11" aria-label="Permalink to &quot;v3.3.8 - for 4.19.11&quot;">​</a></h2><ul><li>Added downloadable mod packages on GitHub Releases.</li></ul><h2 id="v3-3-7-for-4-19-11" tabindex="-1">v3.3.7 - for 4.19.11 <a class="header-anchor" href="#v3-3-7-for-4-19-11" aria-label="Permalink to &quot;v3.3.7 - for 4.19.11&quot;">​</a></h2><ul><li>Any one governor prerequisite now unlocks the next promotion tier.</li><li>Stables now cost 80 production, down from 110.</li><li>Siege units gain 70% combat strength against embarked units.</li></ul><h2 id="v3-3-6-for-4-19-10" tabindex="-1">v3.3.6 - for 4.19.10 <a class="header-anchor" href="#v3-3-6-for-4-19-10" aria-label="Permalink to &quot;v3.3.6 - for 4.19.10&quot;">​</a></h2><ul><li>Water mills can be built away from rivers and grant farms in their city +1 production.</li><li>Fixed the Ancient Districts economic policy applying to the wrong targets.</li><li>Added an online changelog.</li></ul><h2 id="v3-3-5-for-4-19-9" tabindex="-1">v3.3.5 - for 4.19.9 <a class="header-anchor" href="#v3-3-5-for-4-19-9" aria-label="Permalink to &quot;v3.3.5 - for 4.19.9&quot;">​</a></h2><ul><li>On multiplayer speed, research costs 90% of standard and culture costs return to 100%.</li><li>Luxuries grant 2 base happiness plus 2 per city, up to 8 total.</li></ul><h2 id="v3-3-4-for-4-19-9" tabindex="-1">v3.3.4 - for 4.19.9 <a class="header-anchor" href="#v3-3-4-for-4-19-9" aria-label="Permalink to &quot;v3.3.4 - for 4.19.9&quot;">​</a></h2><ul><li>Fixed an issue with Amani&#39;s governor buildings.</li><li>Updated the artwork for most buildings and wonders.</li></ul><h2 id="v3-3-3-for-4-19-9" tabindex="-1">v3.3.3 - for 4.19.9 <a class="header-anchor" href="#v3-3-3-for-4-19-9" aria-label="Permalink to &quot;v3.3.3 - for 4.19.9&quot;">​</a></h2><ul><li>On multiplayer speed, science and culture costs are reduced to 80%.</li><li>Vampires can only be purchased in the capital and have reduced movement and combat strength for three turns after purchase.</li></ul><h2 id="v3-3-2-for-4-19-9" tabindex="-1">v3.3.2 - for 4.19.9 <a class="header-anchor" href="#v3-3-2-for-4-19-9" aria-label="Permalink to &quot;v3.3.2 - for 4.19.9&quot;">​</a></h2><ul><li>The Golden Dawn is available only when Secret Societies mode is enabled.</li><li>Fixed an issue that prevented purchasing governor buildings.</li></ul><h2 id="v3-3-1-for-4-19-9" tabindex="-1">v3.3.1 - for 4.19.9 <a class="header-anchor" href="#v3-3-1-for-4-19-9" aria-label="Permalink to &quot;v3.3.1 - for 4.19.9&quot;">​</a></h2><ul><li>Governor promotions are now selected on the policy screen.</li><li>Korea gains 8% science in cities with a governor and loses 15% in cities without one.</li></ul><h2 id="v3-3-0-for-4-19-9" tabindex="-1">v3.3.0 - for 4.19.9 <a class="header-anchor" href="#v3-3-0-for-4-19-9" aria-label="Permalink to &quot;v3.3.0 - for 4.19.9&quot;">​</a></h2><ul><li>Secret Societies moved from capital buildings to the policy screen.</li><li>Fixed Jesuit Education charging a fixed price for buildings.</li></ul><h2 id="v3-2-x-series-for-4-19-8-4-19-9" tabindex="-1">v3.2.x series (for 4.19.8/4.19.9) <a class="header-anchor" href="#v3-2-x-series-for-4-19-8-4-19-9" aria-label="Permalink to &quot;v3.2.x series (for 4.19.8/4.19.9)&quot;">​</a></h2><ul><li>v3.2.10 increased base city health from 200 to 400.</li><li>v3.2.7 fixed traders failing to use a trade route slot.</li><li>v3.2.6 fixed missing housing, district, and trade route capacity indicators.</li></ul>',36)])])}const g=a(l,[["render",n]]);export{f as __pageData,g as default};
